// Shared by the table and the map: loading the data and formatting values.
// The data is published by liftradar-fetcher (json/, history/, schema/; also archive/ and logs/, not served).

// The page's language. Pages under /pl/ etc. are generated by scripts/translate.mjs, which puts the
// translations of this script's strings in window.STRINGS; the English pages have none.
const LANG = document.documentElement.lang;
const STRINGS = window.STRINGS ?? {};
// The translation of text, which must be a literal for translate.mjs to find it, with its {names} filled in.
// Text after a | is left out in English: it tells apart words that are the same there, but not when translated.
// A plural translation is an object by Intl.PluralRules category, chosen by {n}.
function t(text, values = {}) {
  const found = STRINGS[text] ?? text.split("|")[0];
  const chosen =
    typeof found === "string" ? found : (found[new Intl.PluralRules(LANG).select(values.n)] ?? found.other);
  return chosen.replace(/\{(\w+)\}/g, (_, name) => values[name]);
}
// English keeps the Austrian format the site has always shown.
const DATE_LOCALE = LANG === "en" ? "de-AT" : LANG;

// Absolute: the translated pages are one level down, and share the assets and data.
const INDEX_URL = "/json/index.json";

/** @returns {Promise<Index>} */
async function loadIndex() {
  const response = await fetch(INDEX_URL, { cache: "no-cache" });
  if (!response.ok) throw new Error(`${INDEX_URL}: HTTP ${response.status}`);
  return response.json();
}

// The groups of resorts listed separately (linked ski areas, ski regions), by the id a member's linked_area and
// ski_region give.
const GROUPS_URL = "/json/groups.json";

/** @returns {Promise<Groups["groups"]>} */
async function loadGroups() {
  const response = await fetch(GROUPS_URL, { cache: "no-cache" });
  if (!response.ok) throw new Error(`${GROUPS_URL}: HTTP ${response.status}`);
  return (await response.json()).groups;
}

// Same path layout as liftradar-fetcher's resort_path() and history_path() (core/paths.py).
/** @param {{ country: string, id: string }} r */
const resortPath = (r) => `/json/${r.country}/${r.id}.json`;
/** @param {{ country: string, id: string }} r */
const historyPath = (r) => `/history/${r.country}/${r.id}.json`;
// Experimental: Open-Meteo's forecast for the resort, a file of its own (no file: no forecast).
const weatherPath = (r) => `/json/${r.country}/${r.id}.weather.json`;
// The resort's page (resort.html), e.g. resort.html?r=at/soelden.
/** @param {{ country: string, id: string }} r */
const resortPage = (r) => `resort.html?r=${r.country}/${r.id}`;
// A group's page (area.html): a linked ski area or a pass and its members, e.g. area.html?g=sella-ronda.
/** @param {string} id the group's key in json/groups.json */
const areaPage = (id) => `area.html?g=${id}`;
// A country's page in the page's language (countries.js), e.g. /austria or /de/oesterreich; the table filtered to
// the country for one without a page.
/** @param {string} code */
function countryPagePath(code) {
  const slug = COUNTRY_SLUGS[code]?.[LANG];
  if (!slug) return `./?${new URLSearchParams({ country: code })}`;
  return `${LANG === "en" ? "" : `/${LANG}`}/${slug}`;
}
// The resort and 3D pages are the same HTML for every resort until their script runs: once it has the resort,
// this gives the page its own address for search engines (its canonical, and its translations' in the
// page's <link rel="alternate">), so they aren't taken for duplicates of each other. Those are the addresses
// Cloudflare serves, without .html.
/** @param {{ country: string, id: string }} r */
function setResortAddress(r) {
  const links = /** @type {NodeListOf<HTMLLinkElement>} */ (
    document.querySelectorAll('link[rel="alternate"][hreflang]')
  );
  for (const link of links) link.href += `?r=${r.country}/${r.id}`;
  const own = [...links].find((link) => link.hreflang === document.documentElement.lang);
  if (own) document.head.append(el("link", { rel: "canonical", href: own.href }));
}
// sessionStorage key of the resort list's last filters and order (its query string), set by table.js.
const LIST_KEY = "resort-list";
// The visitor's favourite resorts, kept only in this browser (localStorage, shared by every language) as
// "country/id" keys, in the order they were added. Without storage (private windows, blocked site data) there
// are none, and the stars do nothing lasting.
const FAVORITES_KEY = "favorites";
/** @param {{ country: string, id: string }} r */
const resortKey = (r) => `${r.country}/${r.id}`;
/** @returns {string[]} */
function favorites() {
  try {
    const saved = JSON.parse(localStorage.getItem(FAVORITES_KEY) ?? "[]");
    return Array.isArray(saved) ? saved.filter((key) => typeof key === "string") : [];
  } catch {
    return [];
  }
}
/** @param {{ country: string, id: string }} r */
const isFavorite = (r) => favorites().includes(resortKey(r));
/** @param {{ country: string, id: string }} r */
function toggleFavorite(r) {
  const key = resortKey(r);
  const list = favorites();
  const next = list.includes(key) ? list.filter((k) => k !== key) : [...list, key];
  try {
    localStorage.setItem(FAVORITES_KEY, JSON.stringify(next));
  } catch {}
  favoritesChanged();
}
/** @type {(() => void)[]} */
const favoriteListeners = [];
// Called when the favourites change, here or in another tab.
/** @param {() => void} listener */
const onFavoritesChange = (listener) => favoriteListeners.push(listener);
function favoritesChanged() {
  const list = favorites();
  for (const button of document.querySelectorAll("button.fav"))
    setFavoriteButton(button, list.includes(button.dataset.key));
  for (const listener of favoriteListeners) listener();
}
addEventListener("storage", (event) => {
  if (event.key === FAVORITES_KEY || event.key === null) favoritesChanged();
});
/** @param {HTMLElement} button @param {boolean} on */
function setFavoriteButton(button, on) {
  const label = on ? t("Remove from favourites") : t("Add to favourites");
  button.setAttribute("aria-pressed", String(on));
  button.setAttribute("aria-label", label);
  button.title = label;
}
// A star that adds the resort to the favourites, or removes it; every star of the resort on the page follows.
/** @param {{ country: string, id: string }} r */
function favoriteButton(r) {
  const button = el("button", { type: "button", class: "fav", "data-key": resortKey(r) });
  button.innerHTML =
    '<svg width="18" height="18" viewBox="0 0 24 24" aria-hidden="true" stroke-width="1.8" stroke-linejoin="round">' +
    '<path d="M12 3.5l2.6 5.3 5.8.8-4.2 4.1 1 5.8-5.2-2.7-5.2 2.7 1-5.8-4.2-4.1 5.8-.8z"/></svg>';
  setFavoriteButton(button, isFavorite(r));
  button.addEventListener("click", () => toggleFavorite(r));
  return button;
}
// Back to the list of all resorts, with the filters and order it had in this tab.
function backLink() {
  let list = "";
  try {
    list = sessionStorage.getItem(LIST_KEY) ?? "";
  } catch {}
  const link = el("a", { class: "pill back", href: `./${list}` });
  link.innerHTML =
    '<svg width="16" height="16" viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor"' +
    ' stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M19 12H5M11 6l-6 6 6 6"/></svg>' +
    t("All resorts");
  return link;
}

// The map zoomed in on the resort (map.html), e.g. map.html?r=at/soelden.
/** @param {{ country: string, id: string }} r */
const resortOnMap = (r) => `map.html?r=${r.country}/${r.id}`;

// Lowercase without accents, so "Sölden" sorts and matches like "solden".
// Letters of their own that NFD doesn't take apart into a letter and its mark: "Białka" is found as "bialka".
/** @type {Record<string, string>} */
const LETTERS = { ł: "l", ø: "o", đ: "d", ß: "ss", æ: "ae", œ: "oe", ı: "i", ħ: "h", þ: "th" };
const fold = (text) =>
  text
    .normalize("NFD")
    .replace(/[̀-ͯ]/g, "")
    .toLowerCase()
    .replace(/[łøđßæœıħþ]/g, (c) => LETTERS[c]);

/** @template T @param {T} v @returns {v is NonNullable<T>} */
const present = (v) => v !== null && v !== undefined;
const dash = (value, unit = "") => (value === null || value === undefined ? "–" : `${value}${unit}`);

function pair(a, b, unit = "") {
  const missing = (v) => v === null || v === undefined;
  return missing(a) && missing(b) ? "–" : `${dash(a)}/${dash(b)}${unit}`;
}

const STATUS_LABELS = { open: t("open"), closed: t("closed"), no_report: t("no report") };
const capitalized = (text) => text[0].toUpperCase() + text.slice(1);

// Danger levels and what a bulletin rates; unknown ones are shown as they are published.
const DANGER_NAMES = {
  low: t("low"),
  moderate: t("moderate"),
  considerable: t("considerable"),
  high: t("high"),
  very_high: t("very high"),
  no_snow: t("no snow"),
  no_rating: t("no rating"),
};
const dangerName = (level) => DANGER_NAMES[level] ?? level.replaceAll("_", " ");

// Same as the table and the map.
const STATUS_COLORS = { open: "var(--open)", closed: "var(--closed)", no_report: "var(--none)" };
// A status the site doesn't know (one the fetcher adds before the pages do) is shown as no report, rather than
// breaking the pages that look up its label and colour.
/** @param {IndexResort | Resort} r */
const statusKey = (r) => (STATUS_LABELS[r.status] ? r.status : "no_report");

/** @param {string} iso @param {Intl.DateTimeFormatOptions} [options] */
const viennaTime = (iso, options = { dateStyle: "medium", timeStyle: "short" }) =>
  new Date(iso).toLocaleString(DATE_LOCALE, { timeZone: "Europe/Vienna", ...options });

// When we last read the resort's report (status_from when the latest run couldn't) and when the
// resort last changed it. Stale: an open resort whose report the latest run couldn't read, or that
// hasn't changed for STALE_DAYS (slope maps keep their time while nothing opens or closes).
const STALE_DAYS = 7;
/** @param {Resort} r */
function reportTimes(r) {
  const checked = r.status_from ?? r.fetched_at;
  const changed = r.lifts_updated_at;
  const days = changed ? Math.floor((Date.parse(r.fetched_at) - Date.parse(changed)) / 864e5) : 0;
  const stale = statusKey(r) === "open" && (Boolean(r.status_from) || days > STALE_DAYS);
  return { checked, changed, days, stale };
}

/**
 * One page of a report's sources, with a note where its terms ask for a credit.
 * @param {SourceRef} ref
 * @param {string} [note] after the link, e.g. how many resorts use it
 */
function sourceItem(ref, note = "") {
  const parts = [note, ref.attribution_required ? t("credit required") : ""].filter(Boolean);
  return el(
    "li",
    {},
    el("a", { href: ref.url, rel: "nofollow" }, ref.url),
    parts.length ? el("span", { class: "muted" }, ` (${parts.join(", ")})`) : "",
  );
}

// Fnugg's terms: a visible credit next to its data, linking to the resort's page there.
/** @param {IndexResort | Resort} r */
function fnuggCredit(r) {
  const page = r.country === "no" && r.source_details.conditions.find(({ url }) => url.startsWith("https://fnugg.no/"));
  return page
    ? el("div", { class: "credit" }, t("Snow and lift data provided by "), el("a", { href: page.url }, "fnugg"))
    : "";
}
const regionNames = new Intl.DisplayNames([LANG], { type: "region" });
const countryName = (code) => regionNames.of(code.toUpperCase()) ?? code;

/** @param {Index} index */
function updatedText(index) {
  const time = new Date(index.generated_at);
  const formatted = time.toLocaleString(DATE_LOCALE, {
    timeZone: "Europe/Vienna",
    dateStyle: "medium",
    timeStyle: "short",
  });
  return t("Updated {time}", { time: formatted });
}

// A <details> popover closes on a click elsewhere and on Escape, like the language menu.
/** @param {HTMLDetailsElement} details */
function closeOnOutside(details) {
  document.addEventListener("click", (event) => {
    if (details.open && !details.contains(/** @type {Node} */ (event.target))) details.open = false;
  });
  document.addEventListener("keydown", (event) => {
    if (event.key !== "Escape" || !details.open) return;
    details.open = false;
    details.querySelector("summary")?.focus();
  });
}

function el(tag, attributes = {}, ...children) {
  const node = document.createElement(tag);
  for (const [key, value] of Object.entries(attributes)) node.setAttribute(key, value);
  node.append(...children);
  return node;
}

// The country filter of the table and stats pages: a <details> like the language menu, as a <select> can't
// show flags (style.css, .flag). Choosing a country calls onChoose; the function returned shows one as chosen.
// The arrow keys go through the countries, and Escape or a click elsewhere closes it.
/**
 * @param {HTMLDetailsElement} menu
 * @param {string[]} countries
 * @param {(code: string) => void} onChoose
 * @returns {(code: string) => void}
 */
function countryMenu(menu, countries, onChoose) {
  const summary = /** @type {HTMLElement} */ (menu.querySelector("summary"));
  /** @param {string} code */
  const flag = (code) => {
    const node = el("span", { class: "flag", "data-country": code, "aria-hidden": "true" });
    if (!code)
      node.innerHTML =
        '<svg width="13" height="13" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.4">' +
        '<circle cx="8" cy="8" r="6.5"/><path d="M1.5 8h13M8 1.5c-2.2 2.4-2.2 10.6 0 13M8 1.5c2.2 2.4 2.2 10.6 0 13"/></svg>';
    return node;
  };
  /** @param {string} code */
  const label = (code) => (code ? countryName(code) : t("All countries"));
  const items = ["", ...countries].map((code) => {
    const item = el("button", { type: "button", "data-country": code }, flag(code), label(code));
    item.addEventListener("click", () => {
      menu.open = false;
      summary.focus();
      onChoose(code);
    });
    return item;
  });
  /** @type {HTMLElement} */ (menu.querySelector("div")).replaceChildren(...items);
  document.addEventListener("click", (event) => {
    if (!menu.contains(/** @type {Node} */ (event.target))) menu.open = false;
  });
  menu.addEventListener("keydown", (event) => {
    if (event.key === "Escape" && menu.open) {
      menu.open = false;
      summary.focus();
    } else if (event.key === "ArrowDown" || event.key === "ArrowUp") {
      event.preventDefault();
      menu.open = true;
      const at = items.indexOf(/** @type {HTMLButtonElement} */ (document.activeElement));
      const next =
        at < 0 ? items.findIndex((item) => item.ariaPressed === "true") : at + (event.key === "ArrowDown" ? 1 : -1);
      items[Math.max(0, Math.min(items.length - 1, next))].focus();
    }
  });
  return (code) => {
    summary.replaceChildren(flag(code), el("span", {}, label(code)));
    summary.setAttribute("aria-label", `${t("Country")}: ${label(code)}`);
    for (const item of items) item.setAttribute("aria-pressed", String(item.dataset.country === code));
  };
}

// The apps' loader (LiftRadar's LiftLoader): the logo's gondolas going up a cable, 3.6 s each, while data
// loads. The cabins move in style.css (.lift-loader), and stand still with reduced motion. `small` for
// a narrow place (half the size, the caption beside it); without `caption`, only screen readers say it.
const LIFT_LOADER_CABINS = (() => {
  // A rounded rectangle, for the cabin and its window (cut out of it).
  const box = (x, y, w, h, r) =>
    `M${x + r} ${y}h${w - 2 * r}a${r} ${r} 0 0 1 ${r} ${r}v${h - 2 * r}a${r} ${r} 0 0 1 -${r} ${r}` +
    `h-${w - 2 * r}a${r} ${r} 0 0 1 -${r} -${r}v-${h - 2 * r}a${r} ${r} 0 0 1 ${r} -${r}z`;
  // Each at its grip on the cable: the hanger, the grip, and the cabin (as the logo's).
  const cabin =
    '<path d="M0 0v9" stroke="var(--fg)" stroke-width="1.8"/><circle r="2.4" fill="var(--fg)"/>' +
    `<path fill="var(--accent)" fill-rule="evenodd" d="${box(-11, 9, 22, 21, 5)}${box(-7.6, 13, 15.2, 7.6, 1.8)}"/>`;
  return (
    '<svg viewBox="0 0 168 96" aria-hidden="true">' +
    '<path d="M6 66 162 8" stroke="var(--muted)" stroke-opacity=".7" stroke-width="1.6" stroke-linecap="round"/>' +
    '<circle cx="6" cy="66" r="3" fill="var(--muted)"/><circle cx="162" cy="8" r="3" fill="var(--muted)"/>' +
    `<g class="cabin">${cabin}</g>`.repeat(3) +
    "</svg>"
  );
})();

function liftLoader({ caption = true, small = false } = {}) {
  const node = el("div", { class: small ? "lift-loader small" : "lift-loader", role: "status" });
  node.innerHTML = LIFT_LOADER_CABINS;
  if (caption) node.append(el("span", {}, t("Loading…")));
  else node.setAttribute("aria-label", t("Loading…"));
  return node;
}

// Shared by the resort and area pages: a ski area's members, and the step charts of their history.

// The line under a group member's name, as the apps' lists have it: open, how many lifts and km of slopes are open,
// the snow on the mountain and the fresh snow; closed or without a report, that and how many it has.
/** @param {IndexResort} r */
function memberSummary(r) {
  const status = statusKey(r);
  const open = status === "open";
  const { lifts, slopes, snow } = r;
  const parts = open ? [] : [capitalized(STATUS_LABELS[status])];
  if (lifts?.total) parts.push(t("{n} lifts", { n: open ? pair(lifts.open, lifts.total) : lifts.total }));
  if (slopes?.total_km) {
    parts.push(open ? pair(slopes.open_km, slopes.total_km, " km") : t("{km} km of slopes", { km: slopes.total_km }));
  } else if (slopes?.total) {
    parts.push(t("{n} slopes", { n: open ? pair(slopes.open, slopes.total) : slopes.total }));
  }
  if (open && snow.mountain_cm !== null && snow.mountain_cm !== undefined) parts.push(`${snow.mountain_cm} cm`);
  // Not "summary": the page's key numbers have that class, a grid that would put the fresh snow on a line of its own.
  const line = el("div", { class: "meta numbers" }, parts.join(" · ") || capitalized(STATUS_LABELS[status]));
  if (snow.fresh_cm) line.append(" ", el("span", { class: "fresh" }, `+${snow.fresh_cm}`));
  return line;
}

// The country most of a group's members are in, the one a member from elsewhere is flagged against (Champéry and
// Morgins in Les Portes du Soleil). Where countries are level, `own`'s (the resort whose page it is) if it is one
// of them, else the first member's. The apps do the same (ResortGroup's mainCountry).
/** @param {string[]} members @param {string} own */
function mainCountry(members, own) {
  const countries = members.map((key) => key.split("/")[0]);
  /** @type {Map<string, number>} */
  const counts = new Map();
  for (const c of countries) counts.set(c, (counts.get(c) ?? 0) + 1);
  const most = Math.max(0, ...counts.values());
  if (counts.get(own) === most) return own;
  return countries.find((c) => counts.get(c) === most) ?? own;
}

// A group's members (keys) in the order its card shows them, as the list starts: the open ones first, the most open
// slopes first (then open km, open lifts); then the closed ones and those without a report, the biggest first (km of
// slopes, then lifts); last the ones the index doesn't have. Level, as the group lists them. The apps do the same
// (ResortGroup's ordered).
/** @param {string[]} keys @param {Map<string, IndexResort>} resorts */
function orderedMembers(keys, resorts) {
  /** @param {number | null | undefined} v */
  const n = (v) => -(v ?? -1);
  /** @param {string} key @returns {number[]} */
  const rank = (key) => {
    const r = resorts.get(key);
    if (!r) return [2];
    return statusKey(r) === "open"
      ? [0, n(r.slopes?.open), n(r.slopes?.open_km), n(r.lifts?.open)]
      : [1, n(r.slopes?.total_km), n(r.lifts?.total)];
  };
  const ranks = new Map(keys.map((key) => [key, rank(key)]));
  return [...keys].sort((a, b) => {
    const x = ranks.get(a) ?? [],
      y = ranks.get(b) ?? [];
    for (let i = 0; i < Math.min(x.length, y.length); i++) if (x[i] !== y[i]) return x[i] - y[i];
    return x.length - y.length;
  });
}

// Nice upper bound for the y axis: 1, 2 or 5 times a power of ten.
function niceMax(v) {
  if (v <= 0) return 1;
  const power = 10 ** Math.floor(Math.log10(v));
  return [1, 2, 5, 10].map((m) => m * power).find((m) => m >= v) ?? 10 * power;
}

// A step line (values hold until the next run), redrawn when its box resizes.
function chart(title, unit, colour, points) {
  const box = el("div", { class: "chart" }, el("h3", {}, title));
  const known = points.filter((p) => present(p.v));
  if (known.length < 2) {
    box.append(el("p", { class: "empty" }, t("Not enough runs yet.")));
    return box;
  }
  const svgNS = "http://www.w3.org/2000/svg";
  const svg = document.createElementNS(svgNS, "svg");
  // For screen readers, the chart in words: its latest value, and since when it runs (the line itself, and the
  // hover's values, only show it).
  const latest = known.at(-1);
  const day = (/** @type {Date} */ d) => viennaTime(d.toISOString(), { day: "numeric", month: "short" });
  svg.setAttribute("role", "img");
  svg.setAttribute(
    "aria-label",
    t("{title}: {value} on {date}, since {start}", {
      title,
      value: `${Math.round(latest.v * 10) / 10}${unit ? ` ${unit}` : ""}`,
      date: day(latest.t),
      start: day(points[0].t),
    }),
  );
  const tip = el("div", { class: "tip", hidden: "" });
  box.append(svg, tip);
  const node = (tag, attributes) => {
    const n = document.createElementNS(svgNS, tag);
    for (const [k, v] of Object.entries(attributes)) n.setAttribute(k, v);
    return n;
  };
  const format = (v) => `${Math.round(v * 10) / 10}${unit ? ` ${unit}` : ""}`;
  const H = 150,
    top = 10,
    bottom = 20,
    left = 34,
    right = 10;

  const draw = () => {
    const W = box.clientWidth;
    if (!W) return;
    svg.replaceChildren();
    svg.setAttribute("viewBox", `0 0 ${W} ${H}`);
    const t0 = points[0].t.getTime(),
      t1 = Math.max(points.at(-1).t.getTime(), t0 + 1);
    const max = niceMax(Math.max(...known.map((p) => p.v)));
    const x = (t) => left + ((t.getTime() - t0) / (t1 - t0)) * (W - left - right);
    const y = (v) => top + (1 - v / max) * (H - top - bottom);
    for (const v of [0, max / 2, max]) {
      svg.append(node("line", { class: "grid", x1: left, x2: W - right, y1: y(v), y2: y(v) }));
      const text = node("text", { class: "axis", x: left - 6, y: y(v) + 3, "text-anchor": "end" });
      text.textContent = String(v);
      svg.append(text);
    }
    for (const [t, anchor] of [
      [points[0].t, "start"],
      [points.at(-1).t, "end"],
    ]) {
      const text = node("text", { class: "axis", x: x(t), y: H - 4, "text-anchor": anchor });
      text.textContent = t.toLocaleDateString(DATE_LOCALE, {
        timeZone: "Europe/Vienna",
        day: "numeric",
        month: "short",
      });
      svg.append(text);
    }
    let d = "",
      previous = null;
    for (const p of points) {
      if (!present(p.v)) {
        previous = null;
        continue;
      }
      d += previous ? ` H${x(p.t)} V${y(p.v)}` : ` M${x(p.t)} ${y(p.v)}`;
      previous = p;
    }
    svg.append(node("path", { d, fill: "none", stroke: colour, "stroke-width": 2, "stroke-linejoin": "round" }));
    const last = known.at(-1);
    svg.append(
      node("circle", { cx: x(last.t), cy: y(last.v), r: 4, fill: colour, stroke: "var(--bg)", "stroke-width": 2 }),
    );

    // Hover: the value in force at the pointer (the latest run before it).
    const cursor = node("line", {
      x1: 0,
      x2: 0,
      y1: top,
      y2: H - bottom,
      stroke: "var(--muted)",
      "stroke-dasharray": "2 3",
      visibility: "hidden",
    });
    const dot = node("circle", { r: 4, fill: colour, stroke: "var(--bg)", "stroke-width": 2, visibility: "hidden" });
    const hit = node("rect", { x: left, y: 0, width: W - left - right, height: H, fill: "transparent" });
    svg.append(cursor, dot, hit);
    const hide = () => {
      cursor.setAttribute("visibility", "hidden");
      dot.setAttribute("visibility", "hidden");
      tip.hidden = true;
    };
    hit.addEventListener("pointermove", (event) => {
      const px = event.clientX - svg.getBoundingClientRect().left;
      const p = [...points].reverse().find((q) => x(q.t) <= px + 1) ?? points[0];
      if (!present(p.v)) return hide();
      for (const [n, k, v] of [
        [cursor, "x1", x(p.t)],
        [cursor, "x2", x(p.t)],
        [dot, "cx", x(p.t)],
        [dot, "cy", y(p.v)],
      ])
        n.setAttribute(k, v);
      cursor.setAttribute("visibility", "visible");
      dot.setAttribute("visibility", "visible");
      tip.hidden = false;
      tip.textContent = `${format(p.v)} · ${viennaTime(p.t.toISOString(), { day: "numeric", month: "short", hour: "2-digit", minute: "2-digit" })}`;
      tip.style.left = `${x(p.t)}px`;
      tip.style.top = `${y(p.v) + box.querySelector("h3").offsetHeight - 6}px`;
    });
    hit.addEventListener("pointerleave", hide);
  };
  new ResizeObserver(draw).observe(box);
  return box;
}
